@startuml
class Resident {
  +name : string
  +streetAddress : string
  +phoneNumber : string
  +emailAddress : string
}

class PickupRequest {
  +streetAddress : string
  +description : string
  +pickupTime : time
}

class Vehicle {
  +storageSpace : float
}

class PickupRoute {
  +date : date
}

class VolunteerDriver {
  +availableDays : string[]
}

class Article {
  +description : string
  +dimensions : string
  +weight : float
  +category : string
}

class H2SLocation {
}

class H2SEmployee {
}

class Client {
  +homeAddress : string
  +neededCategories : string[]
}

class FoodBank {
}

class Delivery {
}

Resident "1" -- "*" PickupRequest : places
PickupRequest "1" -- "1" Resident : for
PickupRequest "*" -- "1" Vehicle : scheduled for
PickupRequest "*" -- "1" PickupRoute : part of
PickupRoute "1" -- "1" Vehicle : assigned to
PickupRoute "1" -- "0..1" VolunteerDriver : driven by
Article "*" -- "1" PickupRequest : collected from
Article "1" -- "1" H2SLocation : processed at
Article "1" -- "1" H2SLocation : categorized by
H2SLocation "1" -- "*" H2SEmployee : employs
H2SLocation "1" -- "*" H2SLocation : operates in
Client "0..1" -- "1" H2SLocation : receives from
Client "1" -- "*" Delivery : receives
Delivery "1" -- "1" VolunteerDriver : performed by
Delivery "1" -- "1" Article : delivers
Delivery "1" -- "1" Client : to
Article "0..1" -- "1" FoodBank : dropped off at
@enduml

